def timsort(the_array):
    def insertion_sort(the_array, left=0, right=None):
        if right is None:
            right = len(the_array) - 1
        for i in range(left + 1, right + 1):
            key = the_array[i]
            j = i - 1
            while j >= left and the_array[j] > key:
                the_array[j + 1] = the_array[j]
                j -= 1
            the_array[j + 1] = key
        return the_array

    def merge(left, right):
        result = []
        while left and right:
            if left[0] <= right[0]:
                result.append(left.pop(0))
            else:
                result.append(right.pop(0))
        result.extend(left)
        result.extend(right)
        return result

