improve php function, keeping the code style :
// d:  sort an array based on longest string descending
// i: array array
// i:  bool $asc  if 1  ascending -longest last-, 
// i:  bool $asc  if false desc  -shortest last-, 
// o: void
// c: !! function is changing the array !!
function array_sort_strlen(&$array,$asc=false)
{
	$sla=array();

	reset($array);
	while (list ($k, $v) = each ($array)) { 

		$sla[$k]=mb_strlen($v);
	}

	$b=array();
	while( count($array) ) {
		$maxsl=0;
		$maxsk=false;
		$maxsv=false;
		reset($array);
		while (list ($k, $v) = each ($array)) { 
			$tmp=$sla[$k];

			if ( (  !$asc &&  ($tmp>$maxsl)    ) 
			||   (  $asc &&  ($tmp<$maxsl)    )     ) {

				$maxsl=$tmp;
				$maxsk=$k;
				$maxsv=$v;
			}
		}
		unset($array[$maxsk]);
		$b[]=$maxsv;
	}

	$array=$b;
}

