float hash21(vec2 p){
    vec3 p3  = fract(vec3(p.xyx) * .1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}
float valueNoise21(vec2 x) {
    vec2 id = floor(x);
    vec2 guv = fract(x);


	float a = hash21(floor(id + vec2(0.0, 0.0)));
    float b = hash21(floor(id + vec2(1.0, 0.0)));
    float c = hash21(floor(id + vec2(0.0, 1.0)));
    float d = hash21(floor(id + vec2(1.0, 1.0)));

    vec2 t = guv * guv * (3.0 - 2.0 * guv);


    return mix(mix(a,b,t.x),mix(c,d,t.x),t.y);
}

vec3 tint(vec3 col)
{
    vec3 _black = vec3 (0.,0.,0.);
    vec3 _white = vec3(1.0, 1.0, 1.0);
    float _amount = 1.; // 0..1

    vec3 gray = vec3(0.299, 0.587, 0.114);  ///Grayscale coefficient  
    float brightness = dot(col, gray); //Get the brightness value
    vec3 grayColor = vec3(brightness); // Turn into black and white map

    grayColor = mix(_black, _white, grayColor);
    vec3 color = mix(col,grayColor,_amount);
    return color

