dispatch('/api/calendar/events', function () {
  $events = db::dataQuery("SELECT * FROM events");

  if (empty($events)) {
    return json_encode([]);
  } elseif (!hasDepthOfTwoOrMoreInCalendario($events)) {
    $events = [$events];
  }

  foreach ($events as &$event) {
    $start_datetime = new DateTime($event['start'], new DateTimeZone('UTC'));
    $end_datetime = new DateTime($event['end'], new DateTimeZone('UTC'));

    // Add 5 hours to the start and end times
    $start_datetime->modify('+5 hours');
