class CrossEntropyFunction(Function):
    @staticmethod
    def forward(ctx, activations, target):
        lsm = LogSoftmax()
        log_softmax = lsm(activations)
        ctx.save_for_backward(activations, target, log_softmax)

        loss = -torch.gather(log_softmax, 1, target.unsqueeze(1)).mean()

        return loss

    @staticmethod
    def backward(ctx, grad_output):
        activations, target, log_softmax = ctx.saved_tensors

        # Compute the gradient of the cross entropy loss with respect to the activations
        grad_activations = torch.exp(log_softmax) - torch.zeros_like(log_softmax).scatter_(1, target.unsqueeze(1), 1)

        # Multiply the gradient by the grad_output
        grad_activations = grad_activations * grad_output / grad_activations.shape[0]

        return grad_activations, None


class CrossEntropy(nn.Module):
    def __init__(self, ):
        super().__init__()
        self.func = CrossEntropyFunction.apply

    def forward(self, activations, target):
        return self.func(activations, target)
