function drawKochCurve(n, p1, p2) {
  if (n === 0) {
    return [p1, p2];
  }

  var dx = (p2.x - p1.x) / 3;
  var dy = (p2.y - p1.y) / 3;

  var p3 = { x: p1.x + dx, y: p1.y + dy };
  var p4 = { x: p1.x + 2 * dx, y: p1.y + 2 * dy };

  // 60度回転するための中点計算
  var midx = (p3.x + p4.x) / 2;
  var midy = (p3.y + p4.y) / 2;

  // p3 と p4 の距離を計算
  var length = Math.sqrt((p4.x - p3.x) ** 2 + (p4.y - p3.y) ** 2);
  var height = (Math.sqrt(3) / 2) * length;

  // p3 と p4 を基準に、正三角形の頂点 p5 を計算
  var angle = Math.atan2(p4.y - p3.y, p4.x - p3.x) - Math.PI / 2;
  var p5 = {
    x: midx + height * Math.cos(angle),
    y: midy + height * Math.sin(angle)
  };

  var part1 = drawKochCurve(n - 1, p1, p3);
  var part2 = drawKochCurve(n - 1, p3, p5);
  var part3 = drawKochCurve(n - 1, p5, p4);
  var part4 = drawKochCurve(n - 1, p4, p2);

  return part1.concat(part2.slice(1), part3.slice(1), part4.slice(1));
}

